/**
 * Fetch the 88 AMC 12 pages that AMC 10 problems redirect to, where our cache
 * currently holds a stale `wikitext: null` for the target (from a blocked/rate-limited
 * batch on 2026-09-14, not genuine 404s — see CLAUDE.md "known-fragile: the wiki
 * transport"). Until these are re-fetched, in-app statement display silently shows
 * nothing for every cross-listed AMC 10/12 problem (see src/lib/statements.ts, which
 * follows the redirect from cache but can't invent content that isn't there).
 *
 * Paste this whole script into the Chrome DevTools console while on any
 * artofproblemsolving.com page (so Cloudflare cookies are attached to fetch()).
 *
 * It fetches all 88 pages sequentially with a random 4-7s delay between requests,
 * logs progress, and downloads ONE file: redirect-targets-cache.json
 *
 * After downloading, move it into the repo and split it into individual cache files:
 *   mv ~/Downloads/redirect-targets-cache.json data/cache/
 *   node pipeline/split-cache.mjs data/cache/redirect-targets-cache.json
 *
 * Then re-scan for Cloudflare challenge pages before trusting the result:
 *   grep -rl "Just a moment" pipeline/.cache/
 * Any hit means that specific page needs a manual retry (re-run with just that
 * page in TARGETS below).
 *
 * This list was generated by scanning every committed data/exams/*.json for a
 * "#redirect" wikitext stub whose target page is cached with wikitext: null.
 */

const WIKI = "https://artofproblemsolving.com/wiki/index.php";

const TARGETS = ["2019_AMC_12B_Problems/Problem_13","2021_AMC_12A_Problems/Problem_3","2021_AMC_12A_Problems/Problem_4","2021_AMC_12A_Problems/Problem_5","2021_AMC_12A_Problems/Problem_7","2021_AMC_12A_Problems/Problem_9","2021_AMC_12A_Problems/Problem_10","2021_AMC_12A_Problems/Problem_12","2021_AMC_12A_Problems/Problem_16","2021_AMC_12A_Problems/Problem_17","2021_AMC_12A_Problems/Problem_18","2021_AMC_12A_Problems/Problem_23","2021_AMC_12B_Problems/Problem_1","2021_AMC_12B_Problems/Problem_2","2021_AMC_12B_Problems/Problem_4","2021_AMC_12B_Problems/Problem_5","2021_AMC_12B_Problems/Problem_6","2021_AMC_12B_Problems/Problem_7","2021_AMC_12B_Problems/Problem_8","2021_AMC_12B_Problems/Problem_12","2021_AMC_12B_Problems/Problem_15","2021_AMC_12B_Problems/Problem_22","2021_AMC_12B_Problems/Problem_25","2021_Fall_AMC_12A_Problems/Problem_1","2021_Fall_AMC_12A_Problems/Problem_2","2021_Fall_AMC_12A_Problems/Problem_3","2021_Fall_AMC_12A_Problems/Problem_4","2021_Fall_AMC_12A_Problems/Problem_5","2021_Fall_AMC_12A_Problems/Problem_6","2021_Fall_AMC_12A_Problems/Problem_7","2021_Fall_AMC_12A_Problems/Problem_10","2021_Fall_AMC_12A_Problems/Problem_17","2021_Fall_AMC_12A_Problems/Problem_18","2021_Fall_AMC_12A_Problems/Problem_20","2021_Fall_AMC_12A_Problems/Problem_23","2021_Fall_AMC_12B_Problems/Problem_1","2021_Fall_AMC_12B_Problems/Problem_2","2021_Fall_AMC_12B_Problems/Problem_3","2021_Fall_AMC_12B_Problems/Problem_4","2021_Fall_AMC_12B_Problems/Problem_5","2021_Fall_AMC_12B_Problems/Problem_6","2021_Fall_AMC_12B_Problems/Problem_7","2021_Fall_AMC_12B_Problems/Problem_11","2021_Fall_AMC_12B_Problems/Problem_19","2021_Fall_AMC_12B_Problems/Problem_20","2023_AMC_12A_Problems/Problem_1","2023_AMC_12A_Problems/Problem_2","2023_AMC_12A_Problems/Problem_3","2023_AMC_12A_Problems/Problem_4","2023_AMC_12A_Problems/Problem_5","2023_AMC_12A_Problems/Problem_7","2023_AMC_12A_Problems/Problem_8","2023_AMC_12A_Problems/Problem_9","2023_AMC_12A_Problems/Problem_13","2023_AMC_12A_Problems/Problem_18","2023_AMC_12A_Problems/Problem_21","2023_AMC_12B_Problems/Problem_1","2023_AMC_12B_Problems/Problem_2","2023_AMC_12B_Problems/Problem_3","2023_AMC_12B_Problems/Problem_4","2023_AMC_12B_Problems/Problem_5","2023_AMC_12B_Problems/Problem_6","2023_AMC_12B_Problems/Problem_9","2023_AMC_12B_Problems/Problem_13","2023_AMC_12B_Problems/Problem_15","2023_AMC_12B_Problems/Problem_19","2023_AMC_12B_Problems/Problem_25","2024_AMC_12B_Problems/Problem_16","2025_AMC_12A_Problems/Problem_1","2025_AMC_12A_Problems/Problem_2","2025_AMC_12A_Problems/Problem_3","2025_AMC_12A_Problems/Problem_4","2025_AMC_12A_Problems/Problem_5","2025_AMC_12A_Problems/Problem_6","2025_AMC_12A_Problems/Problem_12","2025_AMC_12A_Problems/Problem_15","2025_AMC_12A_Problems/Problem_16","2025_AMC_12A_Problems/Problem_23","2025_AMC_12B_Problems/Problem_2","2025_AMC_12B_Problems/Problem_4","2025_AMC_12B_Problems/Problem_6","2025_AMC_12B_Problems/Problem_10","2025_AMC_12B_Problems/Problem_11","2025_AMC_12B_Problems/Problem_14","2025_AMC_12B_Problems/Problem_15","2025_AMC_12B_Problems/Problem_17","2025_AMC_12B_Problems/Problem_19","2025_AMC_12B_Problems/Problem_20"];

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function download(filename, data) {
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(a.href);
  await sleep(1000);
}

async function fetchPage(page, index, total) {
  const url = `${WIKI}?title=${encodeURIComponent(page)}&action=raw`;
  const delay = 4000 + Math.random() * 3000;
  console.log(`[${index + 1}/${total}] waiting ${(delay / 1000).toFixed(1)}s → ${page}`);
  await sleep(delay);
  try {
    const r = await fetch(url);
    const wikitext = r.status === 404 ? null : await r.text();
    if (wikitext && wikitext.includes("Just a moment")) {
      console.warn(`  ⚠ CLOUDFLARE CHALLENGE (not real content) → ${page}`);
    } else if (wikitext === null) {
      console.warn(`  ⚠ genuine 404 → ${page}`);
    } else {
      console.log(`  ✓ ${wikitext.length} chars → ${page}`);
    }
    return { page, wikitext, fetchedAt: new Date().toISOString() };
  } catch (e) {
    console.error(`  ✗ ERROR ${page}: ${e}`);
    return { page, wikitext: null, fetchedAt: new Date().toISOString() };
  }
}

(async () => {
  console.log(`Fetching ${TARGETS.length} redirect-target pages, ~${Math.ceil(TARGETS.length * 5.5 / 60)} min total...\n`);
  const results = [];
  for (let i = 0; i < TARGETS.length; i++) {
    results.push(await fetchPage(TARGETS[i], i, TARGETS.length));
  }

  const ok = results.filter(r => r.wikitext && !r.wikitext.includes("Just a moment")).length;
  const challenged = results.filter(r => r.wikitext && r.wikitext.includes("Just a moment")).length;
  const missing = results.filter(r => r.wikitext === null).length;

  console.log(`\nDone: ${ok}/${TARGETS.length} clean, ${challenged} Cloudflare challenges, ${missing} genuine 404s`);
  await download("redirect-targets-cache.json", results);
  console.log("\nSaved redirect-targets-cache.json to Downloads.");
  console.log("Next steps:");
  console.log("  mv ~/Downloads/redirect-targets-cache.json data/cache/");
  console.log("  node pipeline/split-cache.mjs data/cache/redirect-targets-cache.json");
  console.log("  grep -rl 'Just a moment' pipeline/.cache/   # check for challenge pages needing retry");
})();
